program2='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the shortest repeating horizontal period from the regular part
    # of the patterned field. The first few columns contain seed values.
    candidates = []
    for period in range(1, min(12, w) + 1):
        mismatches = 0
        for r in range(3, h):
            by_residue = {}
            for c in range(6, w):
                value = grid[r][c]
                if value:
                    by_residue.setdefault(c % period, []).append(value)
            for values in by_residue.values():
                mismatches += len(values) - Counter(values).most_common(1)[0][1]
        candidates.append((mismatches, period))
    period = min(candidates)[1]

    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or (r == 2 and c < 2):
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            elif r < 3 or c < 3:
                out[r][c] = 1
            else:
                values = [grid[r][cc] for cc in range(6, w)
                          if grid[r][cc] != 0 and cc % period == c % period]
                if not values:
                    values = [grid[rr][cc] for rr in range(3, h)
                              for cc in range(3, w)
                              if rr + cc == r + c and grid[rr][cc] != 0]
                out[r][c] = Counter(values).most_common(1)[0][0] if values else 1
    return out
'''
